/** action prefix family => v2 resource, matched only if no exact alias exists */
const WX_V2_FAMILIES = [
  'aic_*' => 'ai',
  'dash_*' => 'dashboard',
  'gdata_*' => 'analytics',
  'notify_*' => 'notifications',
  'sag_*' => 'seo',
  'seo_*' => 'seo',
